package com.cryptostrategy.platform.evaluation.internal;
import com.cryptostrategy.platform.backtesting.api.model.BacktestResult;import com.cryptostrategy.platform.evaluation.api.model.*;import java.math.*;import java.time.Instant;
public final class DeterministicEvaluator {private final MetricCalculator calculator=new MetricCalculator();public EvaluationResult evaluate(BacktestResult result,MetricVersion metricVersion,RankingVersion rankingVersion){var m=calculator.calculate(result);BigDecimal r=clamp(m.totalReturn()),w=clamp(m.winRate()),d=BigDecimal.ONE.setScale(10).subtract(clamp(m.maximumDrawdown()));BigDecimal overall=r.multiply(new BigDecimal("0.45")).add(w.multiply(new BigDecimal("0.30"))).add(d.multiply(new BigDecimal("0.25"))).setScale(10,RoundingMode.HALF_EVEN);var normalized=new NormalizedMetrics(r,w,d,overall);String fingerprint=new EvaluationFingerprintV1().calculate(result.fingerprint(),metricVersion,rankingVersion,m,normalized);return new EvaluationResult(EvaluationResultId.generate(),result.experimentId(),result.resultId(),metricVersion,rankingVersion,m.totalReturn(),m.winRate(),m.maximumDrawdown(),m.numberOfTrades(),overall,m.numberOfTrades()>=5,fingerprint,Instant.now());}private static BigDecimal clamp(BigDecimal v){return v.max(BigDecimal.ZERO).min(BigDecimal.ONE).setScale(10,RoundingMode.HALF_EVEN);}}
